<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/customer-auth.php';
require_once dirname(__DIR__).'/crm/core.php';
function la_installed():bool{if(!crm_query("SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='nd_lc_access_jobs'")->fetchColumn())return false;return crm_query("SELECT state FROM nd_schema_migrations WHERE version='021_paid_access_jobs'")->fetchColumn()==='applied';}
function la_queue(int $order,?int $transaction=null):void{
 $o=crm_record('orders',$order,true);
 crm_query("INSERT INTO nd_lc_access_jobs(order_id,customer_id,triggering_transaction_id) VALUES (?,?,?) ON DUPLICATE KEY UPDATE triggering_transaction_id=COALESCE(VALUES(triggering_transaction_id),triggering_transaction_id),next_attempt=IF(state IN ('PENDING','BLOCKED'),UTC_TIMESTAMP(),next_attempt)",[$order,$o['customer_id'],$transaction]);
 crm_notice('paid-access:'.$order,'orders',$order,'Задача доступа после оплаты: система проверяет условия приглашения.');
}
function la_reason(array $j):?string{
 $o=crm_record('orders',(int)$j['order_id']);if((int)$o['customer_id']!==(int)$j['customer_id']||$o['archived_at']!==null)return 'order_unavailable';
 if(!ca_paid_order((int)$j['customer_id'],(int)$j['order_id']))return 'initial_payment_incomplete';
 if(!ca_privacy_settings()['enabled'])return 'policy_not_approved';if(!ca_enabled())return 'portal_closed';if(!ca_mail_ready())return 'mail_not_verified';
 $c=crm_record('customers',(int)$j['customer_id']);if($c['status']!=='active')return 'customer_unavailable';$email=$c['email']??'';if(!is_string($email)||!filter_var($email,FILTER_VALIDATE_EMAIL)||!preg_match('/^[\x21-\x7e]+$/D',$email))return 'recipient_missing';
 $party=crm_query("SELECT data_json,state FROM nd_lc_customer_details WHERE order_id=? ORDER BY id DESC LIMIT 1",[$j['order_id']])->fetch();
 $isPackage=(bool)crm_query('SELECT a.binding_id FROM nd_lc_pdf_assets a JOIN nd_lc_document_bindings b ON b.id=a.binding_id JOIN nd_lc_templates t ON t.id=b.template_id WHERE b.order_id=? AND t.kind=\'agreement\' AND b.state=\'AGREED\' LIMIT 1',[$j['order_id']])->fetchColumn();
 if($isPackage&&(!$party||$party['state']!=='APPROVED'))return 'details_not_reviewed';if($party&&$party['state']==='APPROVED'&&mb_strtolower(json_decode($party['data_json'],true)['email']??'')!==mb_strtolower($email))return 'recipient_review_required';return null;
}
function la_view(int $order):array{
 $j=crm_query('SELECT * FROM nd_lc_access_jobs WHERE order_id=?',[$order])->fetch();if(!$j)return ['state'=>'NOT_CREATED','delivery_confirmed'=>false];
 if($j['account_id']){$a=ca_account((int)$j['account_id']);if($a&&$a['email_verified_at']!==null){$j['state']=$j['issued_token_hash']!==null?'ACTIVATED':'EXISTING_ACCOUNT';$j['activated_at']=gmdate('Y-m-d H:i:s',(int)$a['email_verified_at']);}}
 return array_intersect_key($j,array_flip(['order_id','customer_id','state','blocked_code','account_id','attempts','next_attempt','smtp_accepted_at','activated_at','manual_reason','version']))+['delivery_confirmed'=>$j['state']==='ACTIVATED','evidence'=>$j['state']==='ACTIVATED'?'invitation_redeemed_and_account_email_verified':($j['state']==='EXISTING_ACCOUNT'?'existing_verified_account':($j['smtp_accepted_at']?'smtp_acceptance_only':'not_delivered'))];
}
/** Account then token locking follows the existing invitation consumption order.
 * The raw invitation secret exists only in this request's memory and the email. */
function la_run(int $order):array{
 $pending=crm_atomic(function()use($order){
  $j=crm_query('SELECT * FROM nd_lc_access_jobs WHERE order_id=? FOR UPDATE',[$order])->fetch();if(!$j)return null;
  if($j['account_id']){$a=ca_account((int)$j['account_id']);if($a&&$a['email_verified_at']!==null){crm_query("UPDATE nd_lc_access_jobs SET state=?,activated_at=COALESCE(activated_at,?),blocked_code=NULL,version=version+1 WHERE order_id=?",[$j['issued_token_hash']!==null?'ACTIVATED':'EXISTING_ACCOUNT',gmdate('Y-m-d H:i:s',(int)$a['email_verified_at']),$order]);return null;}}
  if($j['state']==='SMTP_ACCEPTED'){crm_query('UPDATE nd_lc_access_jobs SET next_attempt=DATE_ADD(UTC_TIMESTAMP(),INTERVAL 300 SECOND) WHERE order_id=?',[$order]);$token=crm_query('SELECT expires_at,used_at FROM nd_customer_tokens WHERE token_hash=?',[$j['issued_token_hash']])->fetch();if(!$token||(int)$token['expires_at']<=time()){crm_query("UPDATE nd_lc_access_jobs SET state='EXPIRED',blocked_code='invitation_expired',version=version+1 WHERE order_id=?",[$order]);}return null;}
  if(in_array($j['state'],['ACTIVATED','EXISTING_ACCOUNT','UNCERTAIN','EXPIRED'],true)){crm_query('UPDATE nd_lc_access_jobs SET next_attempt=DATE_ADD(UTC_TIMESTAMP(),INTERVAL 300 SECOND) WHERE order_id=?',[$order]);return null;}
  if($j['state']==='PROCESSING'){if($j['lease_until']!==null&&$j['lease_until']<gmdate('Y-m-d H:i:s'))crm_query("UPDATE nd_lc_access_jobs SET state='UNCERTAIN',blocked_code='delivery_uncertain',lease_token=NULL,lease_until=NULL,version=version+1 WHERE order_id=?",[$order]);return null;}
  if((int)$j['attempts']>=5||$j['next_attempt']>gmdate('Y-m-d H:i:s'))return null;
  $block=la_reason($j);if($block){crm_query("UPDATE nd_lc_access_jobs SET state='BLOCKED',blocked_code=?,next_attempt=DATE_ADD(UTC_TIMESTAMP(),INTERVAL 60 SECOND),version=version+1 WHERE order_id=?",[$block,$order]);return null;}
  $c=crm_record('customers',(int)$j['customer_id']);$email=ca_email(['email'=>$c['email']]);$existing=crm_query('SELECT id FROM nd_customer_accounts WHERE email=? FOR UPDATE',[$email])->fetchColumn();
  if($existing){$a=ca_account((int)$existing,true);if(!$a||(int)$a['customer_id']!==(int)$j['customer_id']||$a['status']==='disabled'){crm_query("UPDATE nd_lc_access_jobs SET state='BLOCKED',blocked_code='account_conflict',next_attempt=DATE_ADD(UTC_TIMESTAMP(),INTERVAL 300 SECOND),version=version+1 WHERE order_id=?",[$order]);return null;}
   if(ca_account_allowed($a)){crm_query("UPDATE nd_lc_access_jobs SET state='EXISTING_ACCOUNT',account_id=?,blocked_code=NULL,version=version+1 WHERE order_id=?",[$a['id'],$order]);return null;}
   if($a['registration_method']!=='invitation'){crm_query("UPDATE nd_lc_access_jobs SET state='BLOCKED',blocked_code='account_conflict',version=version+1 WHERE order_id=?",[$order]);return null;}
   if(crm_query("SELECT token_hash FROM nd_customer_tokens WHERE account_id=? AND purpose='invite' AND used_at IS NULL AND expires_at>? LIMIT 1",[$a['id'],time()])->fetchColumn()){crm_query("UPDATE nd_lc_access_jobs SET state='UNCERTAIN',account_id=?,blocked_code='active_invitation_exists',version=version+1 WHERE order_id=?",[$a['id'],$order]);return null;}$account=(int)$a['id'];
  }else{crm_record('customers',(int)$j['customer_id'],true);crm_query('INSERT INTO nd_customer_accounts(customer_id,email) VALUES (?,?)',[$j['customer_id'],$email]);$account=(int)db()->lastInsertId();crm_query("INSERT INTO nd_customer_auth(account_id,registration_method,consent_at,policy_version,policy_hash) VALUES (?,'invitation',0,'','')",[$account]);ca_event('invited',$account,1);}
  $raw=ca_issue($account,'invite',1);$lease=bin2hex(random_bytes(32));crm_query("UPDATE nd_lc_access_jobs SET state='PROCESSING',account_id=?,issued_token_hash=?,attempts=attempts+1,lease_token=?,lease_until=DATE_ADD(UTC_TIMESTAMP(),INTERVAL 120 SECOND),blocked_code=NULL,version=version+1 WHERE order_id=?",[$account,hash('sha256',$raw),$lease,$order]);ca_event('automatic_paid_invitation_issued',$account,1);return ['account'=>$account,'email'=>$email,'raw'=>$raw,'lease'=>$lease];
 });
 if(!$pending)return la_view($order);
 $GLOBALS['customer_smtp_outcome']='not_accepted';$ok=false;try{$ok=ca_send($pending['account'],$pending['email'],'invite',$pending['raw']);}catch(Throwable $e){$ok=false;}
 $uncertain=!$ok&&($GLOBALS['customer_smtp_outcome']??'not_accepted')==='uncertain';crm_atomic(function()use($order,$pending,$ok,$uncertain){$j=crm_query('SELECT * FROM nd_lc_access_jobs WHERE order_id=? FOR UPDATE',[$order])->fetch();if(!$j||!hash_equals($j['lease_token']??'',$pending['lease']))return;if(!$ok&&!$uncertain)crm_query('UPDATE nd_customer_tokens SET used_at=? WHERE token_hash=? AND used_at IS NULL',[time(),hash('sha256',$pending['raw'])]);crm_query('UPDATE nd_lc_access_jobs SET state=?,blocked_code=?,smtp_accepted_at=?,next_attempt=DATE_ADD(UTC_TIMESTAMP(),INTERVAL 60 SECOND),lease_until=NULL,lease_token=NULL,version=version+1 WHERE order_id=?',[$ok?'SMTP_ACCEPTED':($uncertain?'UNCERTAIN':'FAILED'),$ok?null:($uncertain?'delivery_uncertain':'smtp_failed'),$ok?gmdate('Y-m-d H:i:s'):null,$order]);crm_notice('paid-access:'.$order.':'.$j['attempts'],'orders',$order,$ok?'Приглашение принято SMTP; получение ещё не подтверждено.':($uncertain?'Результат SMTP неизвестен. Автоматическая повторная отправка остановлена; требуется проверка владельца.':'Приглашение не принято SMTP. Повтор будет выполнен безопасно; платёж сохранён.'));});return la_view($order);
}
function la_pump(int $limit=10):int{if(!la_installed())return 0;$ids=crm_query("SELECT order_id FROM nd_lc_access_jobs WHERE state IN ('PENDING','BLOCKED','PROCESSING','FAILED','SMTP_ACCEPTED','UNCERTAIN') AND next_attempt<=UTC_TIMESTAMP() ORDER BY (state IN ('PENDING','BLOCKED','PROCESSING','FAILED')) DESC,updated_at LIMIT ".min(10,max(1,$limit)))->fetchAll(PDO::FETCH_COLUMN);foreach($ids as $id)la_run((int)$id);return count($ids);}
function la_manual(array $d):array{
 return crm_idempotent('workflow/access-manual',$d,function()use($d){$order=cc_id($d['order_id']??null);$o=crm_record('orders',$order,true);if(!ca_paid_order((int)$o['customer_id'],$order))crm_fail(409,'Сначала подтвердите согласованный первый платёж.');$reason=cc_text($d,'reason',3000);if(($d['confirm']??false)!==true)crm_fail(422,'Подтвердите ручной повтор и отзыв прежней ссылки.');la_queue($order);$j=crm_query('SELECT * FROM nd_lc_access_jobs WHERE order_id=? FOR UPDATE',[$order])->fetch();crm_version($d,$j);if(($j['account_id']&&ca_account_allowed(ca_account((int)$j['account_id'])))||in_array($j['state'],['ACTIVATED','EXISTING_ACCOUNT','PROCESSING'],true))crm_fail(409,'Аккаунт уже активирован или отправка выполняется.');if($j['account_id']){ca_account((int)$j['account_id'],true);crm_query("UPDATE nd_customer_tokens SET used_at=COALESCE(used_at,?) WHERE account_id=? AND purpose='invite' AND used_at IS NULL",[time(),$j['account_id']]);}crm_query("UPDATE nd_lc_access_jobs SET state='PENDING',blocked_code=NULL,attempts=0,next_attempt=UTC_TIMESTAMP(),manual_reason=?,version=version+1 WHERE order_id=?",[$reason,$order]);lc_audit(['type'=>'owner','id'=>1],'order',$order,'manual_invitation_retry',null,['reason'=>$reason,'previous_state'=>$j['state']]);return ['ok'=>true,'order_id'=>$order];});
}
